(4714917, 679844, 92867, '<td valign="top">Maybe include the ground as well to see how high he was. Nice catch.</td>', 'Maybe include the ground as well to see how high he was. Nice catch.', '2008-05-21 11:58:47.000000', NULL, 1),
(4714931, 680090, 64733, '<td valign="top">Very creative and great abstraction.  Well done!</td>', 'Very creative and great abstraction.  Well done!', '2008-05-21 12:05:24.000000', NULL, 1),
(4714934, 679295, 64733, '<td valign="top">I like the idea, but unfortunately the colors have been washed out.  Seems like the photo is just a few moments too late.</td>', 'I like the idea, but unfortunately the colors have been washed out.  Seems like the photo is just a few moments too late.', '2008-05-21 12:06:17.000000', NULL, 1),
(4714941, 679396, 64733, '<td valign="top">Wow!  Like something out of a bug magazine.  Incredible clarity.</td>', 'Wow!  Like something out of a bug magazine.  Incredible clarity.', '2008-05-21 12:08:38.000000', NULL, 1),
(4714942, 679104, 61961, '<td valign="top">Gorgeous use of light and color, terrific model and location, excellent composition.  The title works, and as a bonus the photo echoes the selective color process of the film itself.  A high score from me.</td>', 'Gorgeous use of light and color, terrific model and location, excellent composition.  The title works, and as a bonus the photo echoes the selective color process of the film itself.  A high score from me.', '2008-05-21 12:09:05.000000', NULL, 1),
(4714943, 680316, 61961, '<td valign="top">A great photo.  I can''t help but give it the highest score despite the fact that the subject disturbs me.</td>', 'A great photo.  I can''t help but give it the highest score despite the fact that the subject disturbs me.', '2008-05-21 12:09:08.000000', NULL, 1),
(4714953, 679694, 75958, '<td valign="top">The face is a little out of focus.</td>', 'The face is a little out of focus.', '2008-05-21 12:12:56.000000', NULL, 1),
