INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(4717634, 680213, 64989, '<td valign="top">Great tie-in to the movie title.  I also like the light and coloring, add to the nightmare effect.</td>', 'Great tie-in to the movie title.  I also like the light and coloring, add to the nightmare effect.', '2008-05-22 14:48:54.000000', NULL, 1),
(4717635, 680221, 64989, '<td valign="top">Great use of panning to catch the motion of the taxi.</td>', 'Great use of panning to catch the motion of the taxi.', '2008-05-22 14:49:23.000000', NULL, 1),
(4717637, 678694, 64989, '<td valign="top">Very cute.</td>', 'Very cute.', '2008-05-22 14:52:51.000000', NULL, 1),
(4717639, 680316, 64989, '<td valign="top">Haunting. 9</td>', 'Haunting. 9', '2008-05-22 14:53:15.000000', NULL, 1),
(4717652, 680262, 14867, '<td valign="top">Very appealing image, with an impeccable technique: composition, DOF, light, everything''s perfect, nothing to improve here</td>', 'Very appealing image, with an impeccable technique: composition, DOF, light, everything''s perfect, nothing to improve here', '2008-05-22 15:12:19.000000', NULL, 1),
(4717687, 679706, 14867, '<td valign="top">My first reaction was to thing the light could have been better managed <i>but</i> the next one was that the overexposed water contributes to make the image fairy and moving.<br/>Just as if the waterworld beyond the glass was out of reach, unreal.<br/>The children''s attitude is superb.<br/>I like your choice of B&amp;W too - a daring choice making the image different and still more attractive.<br/>The movie''s title is the ice on the cake.</td>', 'My first reaction was to thing the light could have been better managed but the next one was that the overexposed water contributes to make the image fairy and moving.Just as if the waterworld beyond the glass was out of reach, unreal.The children''s attitude is superb.I like your choice of B&W too - a daring choice making the image different and still more attractive.The movie''s title is the ice on the cake.', '2008-05-22 15:32:14.000000', NULL, 1),
(4717716, 680353, 14867, '<td valign="top">Hey, Bruges at blue hour...<br/>Good exposure, I think a thighter crop around the central part of the subject could emphasize your image.<br/>I don''t know your lens, but the distorsion is terrible, all the vertical lines are curved, some raw conversion softwares could fix that</td>', 'Hey, Bruges at blue hour...Good exposure, I think a thighter crop around the central part of the subject could emphasize your image.I don''t know your lens, but the distorsion is terrible, all the vertical lines are curved, some raw conversion softwares could fix that', '2008-05-22 15:40:41.000000', NULL, 1),
(4717721, 679295, 76598, '<td valign="top">Lens flare</td>', 'Lens flare', '2008-05-22 15:41:15.000000', NULL, 1),
