(4720083, 680573, 5746, '<td valign="top">Excellent. Leaves a lot for the imagination. 10 from me.</td>', 'Excellent. Leaves a lot for the imagination. 10 from me.', '2008-05-23 15:27:18.000000', NULL, 1),
(4720100, 680505, 5746, '<td valign="top">I have no idea, how did you achieve such effect in Basic, but it is simply great. The composition is very good.  Light and sky are dramatic, they add to the mood. I love the wood in the background. Just the "Astra" sign is distracting.</td>', 'I have no idea, how did you achieve such effect in Basic, but it is simply great. The composition is very good.  Light and sky are dramatic, they add to the mood. I love the wood in the background. Just the "Astra" sign is distracting.', '2008-05-23 15:42:02.000000', NULL, 1),
(4720101, 679209, 5746, '<td valign="top">Bad Sata indeed :) Veru cute model. And look at his evil look :)</td>', 'Bad Sata indeed :) Veru cute model. And look at his evil look :)', '2008-05-23 15:42:42.000000', NULL, 1),
(4720103, 680081, 53243, '<td valign="top">too cute!</td>', 'too cute!', '2008-05-23 15:42:59.000000', NULL, 1),
(4720106, 680071, 5746, '<td valign="top">Well... simply art. I adore it. Instant 10. I love the colour, the negative space, the pose, everything. It reminds me of old Kurosawa films or Hero, where colours are extremly important symbols. Fantastic picture.</td>', 'Well... simply art. I adore it. Instant 10. I love the colour, the negative space, the pose, everything. It reminds me of old Kurosawa films or Hero, where colours are extremly important symbols. Fantastic picture.', '2008-05-23 15:45:30.000000', NULL, 1),
(4720109, 680451, 5746, '<td valign="top">Brings Brokeback mountain to my mind. But I like this no matter what. It''s crisp. The colours are perfect - from sun-beaten ground and grass through the chestnut horse up to the blue of jeans. I like that you left some air on the left - to the direction, where the horse and rider are heading. The detail is amazing. Nice DOF. Even horse eyelashes are in focus. Perfect.</td>', 'Brings Brokeback mountain to my mind. But I like this no matter what. It''s crisp. The colours are perfect - from sun-beaten ground and grass through the chestnut horse up to the blue of jeans. I like that you left some air on the left - to the direction, where the horse and rider are heading. The detail is amazing. Nice DOF. Even horse eyelashes are in focus. Perfect.', '2008-05-23 15:48:51.000000', NULL, 1),
(4720110, 680434, 5746, '<td valign="top">Could be also suitable for The Great Gatsby :) Excellent detail, fantastic colours. Very, very smooth. Bumping it to 10.</td>', 'Could be also suitable for The Great Gatsby :) Excellent detail, fantastic colours. Very, very smooth. Bumping it to 10.', '2008-05-23 15:49:26.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(4720115, 680337, 5746, '<td valign="top">Very good composition, razor sharp. I like limited colour scheme. The blood looks more like paint, but I don''t care. I like the way you caught the drop. Just as if someone just used this knife in murder. This picture tells a story. No doubt.</td>', 'Very good composition, razor sharp. I like limited colour scheme. The blood looks more like paint, but I don''t care. I like the way you caught the drop. Just as if someone just used this knife in murder. This picture tells a story. No doubt.', '2008-05-23 15:51:28.000000', NULL, 1),
(4720118, 680445, 5746, '<td valign="top">I like it from the first view. Negative space is a good choice. I like the fact, that you did not try to literaly change this flower into black. B&amp;W was a good choice. Good contrast and clarity. Very delicate and elegant flower. Perfect symmetry underlined by your composition.</td>', 'I like it from the first view. Negative space is a good choice. I like the fact, that you did not try to literaly change this flower into black. B&W was a good choice. Good contrast and clarity. Very delicate and elegant flower. Perfect symmetry underlined by your composition.', '2008-05-23 15:53:50.000000', NULL, 1),
(4720121, 680081, 5746, '<td valign="top">The child is amazing :) It looks a bit like modern Madonna with child to me. Great set up, I love the retro feel of this picture. Fantastic model. I can see a story behind it.</td>', 'The child is amazing :) It looks a bit like modern Madonna with child to me. Great set up, I love the retro feel of this picture. Fantastic model. I can see a story behind it.', '2008-05-23 15:55:12.000000', NULL, 1),
(4720122, 680563, 5746, '<td valign="top">Funny portrait of a lovely girl. Love her blue dress which makes her brown eyes and dark hair more prominent. Lovely picture. 9.</td>', 'Funny portrait of a lovely girl. Love her blue dress which makes her brown eyes and dark hair more prominent. Lovely picture. 9.', '2008-05-23 15:56:06.000000', NULL, 1),
(4720125, 680594, 5746, '<td valign="top">Excellent colours. Great attempt on the challenge theme and the title. Funny, yet interesting due to the vibrant colours. 9.</td>', 'Excellent colours. Great attempt on the challenge theme and the title. Funny, yet interesting due to the vibrant colours. 9.', '2008-05-23 15:56:55.000000', NULL, 1),
(4720128, 680454, 5746, '<td valign="top">Simply stunning. I don''t care wheather it is a real galaxy, but it looks like the one. It even recalls map, although an alien map I guess :) Great colours. I like the abstract feel of it. 9.</td>', 'Simply stunning. I don''t care wheather it is a real galaxy, but it looks like the one. It even recalls map, although an alien map I guess :) Great colours. I like the abstract feel of it. 9.', '2008-05-23 15:58:19.000000', NULL, 1),
(4720129, 679756, 5746, '<td valign="top">Oh yes! Just the blue shift would make it better (for "the night" of course). Great. It is also worth mentioning that I simply love this movie :)</td>', 'Oh yes! Just the blue shift would make it better (for "the night" of course). Great. It is also worth mentioning that I simply love this movie :)', '2008-05-23 15:58:23.000000', NULL, 1),
(4720130, 679563, 5746, '<td valign="top">Wooow... Homeless and beggars always are an interesting story. You are brave, I''m afraid to shoot them. Great composition, nice colour scheme, excellent detail, good match on the movie title.</td>', 'Wooow... Homeless and beggars always are an interesting story. You are brave, I''m afraid to shoot them. Great composition, nice colour scheme, excellent detail, good match on the movie title.', '2008-05-23 15:58:28.000000', NULL, 1),
(4720133, 679104, 5746, '<td valign="top">I was wandering if someone will take a chance with Sin City. Your model is not only beautiful but also brave. I hope it''s legal in basic, because I''m rating it high. I like the splash of colour. You captured the mood of the movie perfectly.</td>', 'I was wandering if someone will take a chance with Sin City. Your model is not only beautiful but also brave. I hope it''s legal in basic, because I''m rating it high. I like the splash of colour. You captured the mood of the movie perfectly.', '2008-05-23 15:59:53.000000', NULL, 1),
(4720134, 680488, 5746, '<td valign="top">Do you have time machine handy? Looks like an original photograph. Excellent choice of sepia tones. Very good composition. Good detail.</td>', 'Do you have time machine handy? Looks like an original photograph. Excellent choice of sepia tones. Very good composition. Good detail.', '2008-05-23 16:00:40.000000', NULL, 1),
(4720137, 680353, 5746, '<td valign="top">I like lighting here and well captured dtails. Amazing calmness.</td>', 'I like lighting here and well captured dtails. Amazing calmness.', '2008-05-23 16:01:16.000000', NULL, 1),
