(4722196, 680445, 93411, '<td valign="top">Clean shot, I like it</td>', 'Clean shot, I like it', '2008-05-25 02:05:50.000000', NULL, 1),
(4722197, 679104, 93411, '<td valign="top">The paint on the wall is the only thing that detracted from this shot</td>', 'The paint on the wall is the only thing that detracted from this shot', '2008-05-25 02:06:44.000000', NULL, 1),
(4722199, 679016, 93411, '<td valign="top">Love this shot!  The intensity it brings is great!</td>', 'Love this shot!  The intensity it brings is great!', '2008-05-25 02:08:04.000000', NULL, 1),
(4722202, 680510, 93411, '<td valign="top">I like this shot, maybe some saturation of the sky would give it a nice dynamic</td>', 'I like this shot, maybe some saturation of the sky would give it a nice dynamic', '2008-05-25 02:10:27.000000', NULL, 1),
