(4722209, 680353, 93411, '<td valign="top">Very nice, perfect water for the picture</td>', 'Very nice, perfect water for the picture', '2008-05-25 02:12:23.000000', NULL, 1),
(4722210, 680275, 93411, '<td valign="top">I like it is a fun shot</td>', 'I like it is a fun shot', '2008-05-25 02:13:07.000000', NULL, 1),
(4722211, 680258, 93411, '<td valign="top">Looks like President Bush and Charlie Chaplin mix!!! I LOVE IT!!!!!</td>', 'Looks like President Bush and Charlie Chaplin mix!!! I LOVE IT!!!!!', '2008-05-25 02:13:46.000000', NULL, 1),
(4722212, 680488, 93411, '<td valign="top">Who won?</td>', 'Who won?', '2008-05-25 02:14:11.000000', NULL, 1),
