(4722216, 680416, 93411, '<td valign="top">I see what your going for, not bad!</td>', 'I see what your going for, not bad!', '2008-05-25 02:16:28.000000', NULL, 1),
(4722217, 679396, 93411, '<td valign="top">Thats nasty, Great close up, but nasty!</td>', 'Thats nasty, Great close up, but nasty!', '2008-05-25 02:16:55.000000', NULL, 1),
(4722272, 680053, 82503, '<td valign="top">DNMC, sorry.</td>', 'DNMC, sorry.', '2008-05-25 05:50:25.000000', NULL, 1),
(4722280, 680055, 82503, '<td valign="top">DNMC, sorry.</td>', 'DNMC, sorry.', '2008-05-25 06:02:28.000000', NULL, 1),
(4722320, 680520, 86799, '<td valign="top">The guy on the left doesn''t look very grumpy.</td>', 'The guy on the left doesn''t look very grumpy.', '2008-05-25 07:56:58.000000', NULL, 1),
(4722358, 680459, 91496, '<td valign="top">Nice idea.  Love the frozen water.  Might be too much negative space at the top, maybe a rectangular landscape crop would have worked.  Looks like some sensor dust in the middle of the lemon.</td>', 'Nice idea.  Love the frozen water.  Might be too much negative space at the top, maybe a rectangular landscape crop would have worked.  Looks like some sensor dust in the middle of the lemon.', '2008-05-25 09:32:28.000000', NULL, 1),
(4722365, 680147, 91496, '<td valign="top">Lovely photo.  DOF is spot on.  Not sure whether I like the wing blur, a faster would have frozen them.  Also as I look at it closer the two birds overlap strangly in what I asssume is a optical illusion.</td>', 'Lovely photo.  DOF is spot on.  Not sure whether I like the wing blur, a faster would have frozen them.  Also as I look at it closer the two birds overlap strangly in what I asssume is a optical illusion.', '2008-05-25 09:38:06.000000', NULL, 1),
(4722395, 679924, 77543, '<td valign="top">This is very abstract - I''m not sure what I''m looking at.</td>', 'This is very abstract - I''m not sure what I''m looking at.', '2008-05-25 10:17:26.000000', NULL, 1),
(4722489, 680427, 47974, '<td valign="top">Nice capture. Not sure if I really like the blue tint tho.</td>', 'Nice capture. Not sure if I really like the blue tint tho.', '2008-05-25 12:00:43.000000', NULL, 1),
(4722492, 680416, 47974, '<td valign="top">To soft for my liking.  Parts of the arm are blown out.</td>', 'To soft for my liking.  Parts of the arm are blown out.', '2008-05-25 12:01:55.000000', NULL, 1),
(4722493, 680439, 47974, '<td valign="top">Not really big on food shots, but a great use of DOF.</td>', 'Not really big on food shots, but a great use of DOF.', '2008-05-25 12:02:37.000000', NULL, 1),
(4722506, 678879, 47974, '<td valign="top">Great photo.  One of the best in the challenge.</td>', 'Great photo.  One of the best in the challenge.', '2008-05-25 12:11:09.000000', NULL, 1),
(4722512, 680088, 47974, '<td valign="top">Nice capture, would have been better if the moon was clearer.</td>', 'Nice capture, would have been better if the moon was clearer.', '2008-05-25 12:12:15.000000', NULL, 1),
(4722514, 680449, 47974, '<td valign="top">Nice photo and good conversion to B&amp;W.  Do have two areas with the highlights blown.</td>', 'Nice photo and good conversion to B&W.  Do have two areas with the highlights blown.', '2008-05-25 12:12:54.000000', NULL, 1),
(4722517, 680567, 47974, '<td valign="top">Very nice photo.  It seems that most around here don''t like pet pictures but this is very well done.  Have always loved their blue eyes.</td>', 'Very nice photo.  It seems that most around here don''t like pet pictures but this is very well done.  Have always loved their blue eyes.', '2008-05-25 12:13:56.000000', NULL, 1),
(4722519, 680643, 47974, '<td valign="top">Looks like it was shot with a large aperture, would have been better stopped all the way down.</td>', 'Looks like it was shot with a large aperture, would have been better stopped all the way down.', '2008-05-25 12:14:53.000000', NULL, 1),
